def median(nums):
    if not nums:
        raise ValueError("median of empty list is undefined")
    s = sorted(nums)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    return (s[n // 2 - 1] + s[n // 2]) / 2

